import { marked } from "marked";

export type Book = {
  slug: string;
  title: string;
  author: string;
  year: number;
  rating: number;
  tags: string[];
  html: string;
};

const files = import.meta.glob("../../content/books/*.md", {
  eager: true,
  query: "?raw",
  import: "default"
}) as Record<string, string>;

function parse(slug: string, raw: string): Book {
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
  const meta: Record<string, string> = {};
  for (const line of (m?.[1] ?? "").split(/\r?\n/)) {
    const i = line.indexOf(":");
    if (i > 0) meta[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  const unquote = (s: string) => s.replace(/^(["'])(.*)\1$/, "$2");
  const tags = (meta.tags ?? "")
    .replace(/^\[|\]$/g, "")
    .split(",")
    .map(t => unquote(t.trim()))
    .filter(Boolean);
  return {
    slug,
    title: unquote(meta.title ?? slug),
    author: unquote(meta.author ?? ""),
    year: Number(meta.year),
    rating: Number(meta.rating),
    tags,
    html: marked.parse(m?.[2] ?? raw, { async: false }) as string
  };
}

export const books: Book[] = Object.entries(files)
  .map(([path, raw]) => parse(path.replace(/^.*\//, "").replace(/\.md$/, ""), raw))
  .sort((a, b) => a.title.localeCompare(b.title));

export const getBook = (slug: string) => books.find(b => b.slug === slug);

export const topRated = () =>
  [...books]
    .sort((a, b) => b.rating - a.rating || a.title.localeCompare(b.title))
    .slice(0, 3);

export const allTags = () =>
  [...new Set(books.flatMap(b => b.tags))].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
