import { Title } from "@solidjs/meta";
import { action, useSubmission } from "@solidjs/router";
import { Show, createSignal } from "solid-js";
import { validate, type ContactErrors } from "~/lib/contact";

type Result = {
  values: { name: string; email: string; message: string };
  errors: ContactErrors;
  ok: boolean;
};

const send = action(async (form: FormData): Promise<Result> => {
  "use server";
  const values = {
    name: String(form.get("name") ?? "").trim(),
    email: String(form.get("email") ?? "").trim(),
    message: String(form.get("message") ?? "").trim()
  };
  const errors = validate(values);
  return { values, errors, ok: Object.keys(errors).length === 0 };
}, "contact");

export default function Contact() {
  const sub = useSubmission(send);
  const [clientErrors, setClientErrors] = createSignal<ContactErrors | null>(null);
  const errors = (): ContactErrors => clientErrors() ?? sub.result?.errors ?? {};
  const val = (k: keyof Result["values"]) => sub.result?.values[k] ?? "";

  const onSubmit = (e: SubmitEvent) => {
    const f = new FormData(e.currentTarget as HTMLFormElement);
    const errs = validate({
      name: String(f.get("name") ?? "").trim(),
      email: String(f.get("email") ?? "").trim(),
      message: String(f.get("message") ?? "").trim()
    });
    if (Object.keys(errs).length) {
      e.preventDefault();
      e.stopPropagation();
      setClientErrors(errs);
    } else setClientErrors(null);
  };

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={sub.result?.ok && !clientErrors()}>
        <p>Thanks, {sub.result!.values.name}! Your message has been sent.</p>
      </Show>
      <form action={send} method="post" novalidate onSubmit={onSubmit}>
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={val("name")} />
          <Show when={errors().name}><span>{errors().name}</span></Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={val("email")} />
          <Show when={errors().email}><span>{errors().email}</span></Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message" value={val("message")} />
          <Show when={errors().message}><span>{errors().message}</span></Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
