import { createMiddleware } from "@solidjs/start/middleware";
import { getRequestEvent } from "solid-js/web";
import { validate } from "~/lib/contact";

export default createMiddleware([
  async (event, next) => {
    if (event.req.method === "POST" && new URL(event.req.url).pathname === "/contact") {
      const form = await event.req.formData();
      const get = (k: string) => String(form.get(k) ?? "").trim();
      const values = { name: get("name"), email: get("email"), message: get("message") };
      const errors = validate(values);
      const result = { values, errors, ok: Object.keys(errors).length === 0 };
      if (event.req.headers.get("accept")?.includes("application/json")) {
        return Response.json(result);
      }
      const re = getRequestEvent();
      if (re) re.locals.contact = result;
    }
    return next();
  }
]);
