import { Title } from "@solidjs/meta";
import { Show, createSignal } from "solid-js";
import { getRequestEvent, isServer } from "solid-js/web";
import { validate, type ContactResult, type ContactValues } from "~/lib/contact";

export default function Contact() {
  const initial: ContactResult | null = isServer ? (getRequestEvent()?.locals.contact ?? null) : null;
  const [result, setResult] = createSignal<ContactResult | null>(initial);
  const val = (k: keyof ContactValues) => result()?.values[k] ?? "";
  const errors = () => result()?.errors ?? {};

  const onSubmit = async (e: SubmitEvent) => {
    e.preventDefault();
    const form = e.currentTarget as HTMLFormElement;
    const f = new FormData(form);
    const get = (k: string) => String(f.get(k) ?? "").trim();
    const values = { name: get("name"), email: get("email"), message: get("message") };
    const errs = validate(values);
    if (Object.keys(errs).length) {
      setResult({ values, errors: errs, ok: false });
      return;
    }
    const res = await fetch("/contact", {
      method: "POST",
      headers: { accept: "application/json" },
      body: new URLSearchParams(values)
    });
    setResult(await res.json());
  };

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={result()?.ok}>
        <p>Thanks, {result()!.values.name}! Your message has been sent.</p>
      </Show>
      <form action="/contact" method="post" novalidate onSubmit={onSubmit}>
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={val("name")} />
          <Show when={errors().name}><span>{errors().name}</span></Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={val("email")} />
          <Show when={errors().email}><span>{errors().email}</span></Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message">{val("message")}</textarea>
          <Show when={errors().message}><span>{errors().message}</span></Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
